-- ----------------------------
-- Table structure for revenues
-- ----------------------------
DROP TABLE IF EXISTS `revenues`;
CREATE TABLE `revenues` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `year` smallint unsigned GENERATED ALWAYS AS (year(`date`)) STORED,
  `month` tinyint unsigned GENERATED ALWAYS AS (month(`date`)) STORED,
  `master_opd_id` bigint NOT NULL,
  `master_lokasi_id` bigint DEFAULT NULL,
  `master_retribusi_id` bigint NOT NULL,
  `master_rincian_retribusi_id` bigint DEFAULT NULL,
  `master_sub_rincian_retribusi_id` bigint DEFAULT NULL,
  `total_transactions` int NOT NULL DEFAULT '0',
  `total_revenue` decimal(18,2) NOT NULL DEFAULT '0.00',
  `is_installment` tinyint NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `idx_combination` (`date`,`year`,`month`,`master_opd_id`,`master_lokasi_id`,`master_retribusi_id`,`master_rincian_retribusi_id`,`master_sub_rincian_retribusi_id`,`is_installment`) USING BTREE,
  KEY `idx_date` (`date`) USING BTREE,
  KEY `idx_master_opd_id` (`master_opd_id`) USING BTREE,
  KEY `idx_master_retribusi_id` (`master_retribusi_id`) USING BTREE,
  KEY `idx_master_lokasi_id` (`master_lokasi_id`) USING BTREE,
  KEY `idx_is_installment` (`is_installment`) USING BTREE,
  KEY `idx_year` (`year`) USING BTREE,
  KEY `idx_year_month` (`year`,`month`) USING BTREE,
  KEY `idx_opd_date` (`master_opd_id`,`date`) USING BTREE,
  KEY `idx_retribusi_date` (`master_retribusi_id`,`date`) USING BTREE,
  KEY `idx_lokasi_date` (`master_lokasi_id`,`date`) USING BTREE,
  KEY `idx_installment_date` (`is_installment`,`date`) USING BTREE,
  KEY `idx_year_opd` (`year`,`master_opd_id`) USING BTREE,
  KEY `idx_dashboard_summary` (`date`,`master_retribusi_id`,`total_revenue`,`total_transactions`) USING BTREE,
  KEY `idx_opd_performance` (`master_opd_id`,`date`,`total_revenue`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=103386 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

